c.onpointermove=e=>{if(!drag)return;if(tool==='recognise'){const p=point(e,c),x=Math.min(p.x,drag.x),y=Math.min(p.y,drag.y);crop={x,y,w:Math.max(.01,Math.abs(p.x-drag.x)),h:Math.max(.01,Math.abs(p.y-drag.y))};drawPhoto()}else if(tool==='papercut')cutAt(e)};
