function point(e,c){const r=c.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
function descriptor(c){const d=c.getContext('2d').getImageData(0,0,c.width,c.height).data,w=c.width,h=c.height,gray=new Float32Array(w*h);let mean=0;for(let i=0;i<gray.length;i++){gray[i]=.299*d[i*4]+.587*d[i*4+1]+.114*d[i*4+2];mean+=gray[i]}mean/=gray.length;let v=0;for(const n of gray)v+=(n-mean)**2;const std=Math.sqrt(v/gray.length)||1;const arr=[];for(let y=0;y<8;y++)for(let x=0;x<8;x++){let val=0;for(let yy=y*h/8;yy<(y+1)*h/8;yy++)for(let xx=x*w/8;xx<(x+1)*w/8;xx++)val+=(gray[(yy|0)*w+(xx|0)]-mean)/std;arr.push(val/(w*h/64))}let edge=[];for(let y=0;y<4;y++)for(let x=0;x<4;x++){let v=0;for(let yy=(y*h/4)|0;yy<Math.min(h-1,(y+1)*h/4);yy++)for(let xx=(x*w/4)|0;xx<Math.min(w-1,(x+1)*w/4);xx++){const k=yy*w+xx;v+=(Math.abs(gray[k]-gray[k+1])+Math.abs(gray[k]-gray[k+w]))/255}edge.push(v/(w*h/16))}return [...arr,...edge]}
function extractColors(){const c=cropCanvas(32,32),d=c.getContext('2d').getImageData(0,0,32,32).data;let bins=new Map();for(let i=0;i<d.length;i+=4){const r=Math.round(d[i]/32)*32,g=Math.round(d[i+1]/32)*32,b=Math.round(d[i+2]/32)*32,k=[Math.min(r,255),Math.min(g,255),Math.min(b,255)].join(',');bins.set(k,(bins.get(k)||0)+1)}let candidates=[...bins].sort((a,b)=>b[1]-a[1]).map(([k])=>k.split(',').map(Number));let chosen=[];for(const c of candidates){if(chosen.every(p=>p.reduce((s,v,i)=>s+(v-c[i])**2,0)>3800))chosen.push(c);if(chosen.length===3)break}while(chosen.length<3)chosen.push([[155,53,47],[32,59,70],[185,155,72]][chosen.length]);state.colors=chosen.map(c=>'#'+c.map(v=>v.toString(16).padStart(2,'0')).join('')).concat('#f4f0e6')}
/* Smooth closed contours shared by Canvas and SVG: no pixel rectangles. */
const PAPER=192;
let tileData=null;
function blurField(src,w,h,passes=2){let a=Float32Array.from(src);for(let p=0;p<passes;p++){let b=new Float32Array(a.length);for(let y=0;y<h;y++)for(let x=0;x<w;x++){let sum=0;for(let d=-1;d<=1;d++)sum+=a[y*w+Math.max(0,Math.min(w-1,x+d))];b[y*w+x]=sum/3}let c=new Float32Array(a.length);for(let y=0;y<h;y++)for(let x=0;x<w;x++){let sum=0;for(let d=-1;d<=1;d++)sum+=b[Math.max(0,Math.min(h-1,y+d))*w+x];c[y*w+x]=sum/3}a=c}return a}
function simplifyLine(a,epsilon){if(a.length<=2)return a;const A=a[0],B=a[a.length-1],dx=B[0]-A[0],dy=B[1]-A[1],den=dx*dx+dy*dy;let max=0,at=0;for(let i=1;i<a.length-1;i++){const p=a[i],u=den?Math.max(0,Math.min(1,((p[0]-A[0])*dx+(p[1]-A[1])*dy)/den)):0,dist=Math.hypot(p[0]-A[0]-u*dx,p[1]-A[1]-u*dy);if(dist>max){max=dist;at=i}}if(max<=epsilon)return[A,B];return simplifyLine(a.slice(0,at+1),epsilon).slice(0,-1).concat(simplifyLine(a.slice(at),epsilon))}
function contourPath(binary,w,h,soft=1,minArea=5){const stride=w+1,edges=new Map(),on=(x,y)=>x>=0&&y>=0&&x<w&&y<h&&binary[y*w+x],add=(a,b)=>{if(!edges.has(a))edges.set(a,[]);edges.get(a).push(b)};for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(on(x,y)){const a=y*stride+x,b=a+1,d=a+stride,c=d+1;if(!on(x,y-1))add(a,b);if(!on(x+1,y))add(b,c);if(!on(x,y+1))add(c,d);if(!on(x-1,y))add(d,a)}let result=[];while(edges.size){const first=edges.keys().next().value;let current=first,loop=[],guard=0;do{loop.push([current%stride,Math.floor(current/stride)]);const list=edges.get(current);if(!list)break;const next=list.pop();if(!list.length)edges.delete(current);current=next}while(current!==first&&guard++<w*h*8);if(current!==first||loop.length<4)continue;let area=0;for(let i=0;i<loop.length;i++){const a=loop[i],b=loop[(i+1)%loop.length];area+=a[0]*b[1]-b[0]*a[1]}if(Math.abs(area)/2<minArea)continue;const half=Math.floor(loop.length/2);loop=simplifyLine(loop.slice(0,half+1),soft*1.1).slice(0,-1).concat(simplifyLine(loop.slice(half).concat([loop[0]]),soft*1.1).slice(0,-1));if(loop.length<3)continue;const f=n=>Math.round(n*100)/100,mid=(a,b)=>[f((a[0]+b[0])/2),f((a[1]+b[1])/2)];let start=mid(loop[loop.length-1],loop[0]),d=`M${start[0]} ${start[1]}`;for(let i=0;i<loop.length;i++){let a=loop[i],m=mid(a,loop[(i+1)%loop.length]);d+=`Q${a[0]} ${a[1]} ${m[0]} ${m[1]}`}result.push(d+'Z')}return result.join('')}
function makePattern(){if(!image)return;const n=state.grid,c=cropCanvas(n,Math.round(n*1.5)),data=c.getContext('2d').getImageData(0,0,c.width,c.height).data,rows=c.height;let gray=new Float32Array(n*rows);for(let i=0;i<gray.length;i++)gray[i]=.299*data[i*4]+.587*data[i*4+1]+.114*data[i*4+2];gray=blurField(gray,n,rows,Math.round(state.softness*2));for(let y=0;y<rows;y++)for(let x=0;x<n/2;x++)gray[y*n+n-1-x]=gray[y*n+x];const thresholds=[state.threshold*.65,state.threshold,Math.min(245,state.threshold+45)],paths=thresholds.map(v=>contourPath(Uint8Array.from(gray,g=>g<v?1:0),n,rows,state.softness,10));tileData={n,rows,paths};live=true;drawPattern();status(t('Smooth pattern ready. Adjust edge softness, scale or colours.','平滑纹样已生成，可调整边缘柔和度、重复和配色。'))}
function tileBody(){return [2,1,0].map(i=>`<path fill="${state.colors[i]}" fill-rule="evenodd" d="${tileData.paths[i]}"/>`).join('')}
function patternSVG(){const{n,rows}=tileData,width=n*state.repeat,height=width*.8,body=tileBody();return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="960" viewBox="0 0 ${width} ${height}"><title>Smooth photo-derived repeat / Atlas Studio</title><defs><pattern id="tile" width="${n}" height="${rows*2}" patternUnits="userSpaceOnUse"><rect width="${n}" height="${rows*2}" fill="${state.colors[3]}"/>${body}<g transform="translate(${-n/2},${rows})">${body}</g><g transform="translate(${n/2},${rows})">${body}</g></pattern></defs><rect width="100%" height="100%" fill="url(#tile)"/></svg>`}
function drawPattern(){const c=$('#workCanvas');if(!c||!tileData)return;c.width=1000;c.height=800;const x=c.getContext('2d'),{n,rows,paths}=tileData,scale=c.width/(n*state.repeat),tw=n*scale,th=rows*scale;x.fillStyle=state.colors[3];x.fillRect(0,0,c.width,c.height);const curves=paths.map(d=>new Path2D(d));for(let ry=0;ry<Math.ceil(c.height/th);ry++)for(let rx=-1;rx<state.repeat+1;rx++){x.save();x.translate(rx*tw+(ry%2?tw/2:0),ry*th);x.scale(scale,scale);for(const i of[2,1,0]){x.fillStyle=state.colors[i];x.fill(curves[i],'evenodd')}x.restore()}$('#previewMeta').textContent=t('Smooth vector / ','平滑矢量 / ')+state.repeat+t(' repeats','次重复')}
function pushHistory(){if(mask){history.push(new Uint8Array(mask));if(history.length>30)history.shift()}}
function makePaper(save=true){if(!image){toast(t('Choose a photo or start with blank paper.','请先上传照片，或从空白纸开始。'));return}if(save)pushHistory();const c=cropCanvas(PAPER,PAPER),d=c.getContext('2d').getImageData(0,0,PAPER,PAPER).data;let gray=new Float32Array(PAPER*PAPER);for(let i=0;i<gray.length;i++)gray[i]=.299*d[i*4]+.587*d[i*4+1]+.114*d[i*4+2];gray=blurField(gray,PAPER,PAPER,3);mask=new Uint8Array(PAPER*PAPER);for(let y=8;y<PAPER-8;y++)for(let x=8;x<PAPER-8;x++)mask[y*PAPER+x]=gray[y*PAPER+x]<state.threshold?1:0;live=true;drawPaper();status(t('Smooth paper design ready. Drag to cut or restore.','平滑剪纸已生成，拖动即可剪除或还原。'))}
