function drawPaper(){const c=$('#workCanvas');if(!c||!mask)return;c.width=800;c.height=800;const ctx=c.getContext('2d'),pad=36,size=728;ctx.fillStyle='#e8e5d9';ctx.fillRect(0,0,800,800);ctx.fillStyle='#f6f2e8';ctx.fillRect(pad,pad,size,size);ctx.save();ctx.translate(pad,pad);ctx.scale(size/PAPER,size/PAPER);ctx.fillStyle='#117F85';ctx.fill(new Path2D(`M0 0H${PAPER}V${PAPER}H0Z${paperPath()}`),'evenodd');ctx.restore();if(folded){ctx.fillStyle='#f4f0e6d9';ctx.fillRect(400,pad,364,728);if(state.symmetry>=4)ctx.fillRect(pad,400,364,364);if(state.symmetry===8){ctx.beginPath();ctx.moveTo(pad,pad);ctx.lineTo(pad,400);ctx.lineTo(400,400);ctx.closePath();ctx.fill()}ctx.strokeStyle='#273326';ctx.setLineDash([7,8]);ctx.beginPath();ctx.moveTo(400,pad);ctx.lineTo(400,764);if(state.symmetry>=4){ctx.moveTo(pad,400);ctx.lineTo(764,400)}ctx.stroke();ctx.setLineDash([])}$('#previewMeta').textContent=state.symmetry+t('-way symmetry / smooth curves','向对称 / 平滑曲线')}
