function exportPNG(){const svg=svgOutput();if(!svg){toast(t("Build a pattern or start a paper cut first.","请先生成图案或开始剪纸。"));return}const blob=new Blob([svg],{type:'image/svg+xml'}),u=URL.createObjectURL(blob),im=new Image();im.onload=()=>{const c=getCanvas(1200,tool==='papercut'?1200:960);c.getContext('2d').drawImage(im,0,0,c.width,c.height);c.toBlob(b=>download(b,tool==='papercut'?'atlas-papercut.png':'atlas-photo-repeat.png'));URL.revokeObjectURL(u)};im.onerror=()=>{URL.revokeObjectURL(u);toast(t("PNG export failed. Try the SVG download.","图片导出失败，请下载SVG。"))};im.src=u}
async function findPattern(){if(!image){toast(t('Choose a photo or try a sample first.','请先选择照片或使用样本。'));return}const token=++recognitionToken,b=$('#findPattern'),start=performance.now();b.disabled=true;b.setAttribute('aria-busy','true');b.textContent=t('Comparing…','正在比对…');status(t('Comparing shapes…','正在比对形态…'));await new Promise(r=>setTimeout(r,25));try{const c=cropCanvas(64,64),pixels=c.getContext('2d').getImageData(0,0,64,64).data;let mean=0,sq=0;for(let i=0;i<pixels.length;i+=4){const g=.299*pixels[i]+.587*pixels[i+1]+.114*pixels[i+2];mean+=g;sq+=g*g}const variance=sq/4096-(mean/4096)**2;if(variance<20){status(t('There is too little detail here. Select a clearer motif and try again.','这个区域的细节太少，请选择更清晰的纹样再试。'));return}const d=descriptor(c),ranked=P.map(p=>({p,distance:p.features.reduce((sum,v,i)=>sum+(v-d[i])**2,0)})).sort((a,b)=>a.distance-b.distance).slice(0,3);if(token!==recognitionToken||!b.isConnected)return;results=ranked.map(x=>x.p);$('#matchResults').innerHTML=`<div class="match-heading">${t('Closest visual studies','形态最接近的样本')} <span>${Math.round(performance.now()-start)} ms</span></div>`+ranked.map((x,i)=>`<button class="result" data-pattern="${x.p.id}"><img src="${asset(patternVector(x.p))}" alt="${lang==='en'?x.p.en:x.p.zh}"><div><span class="tag">0${i+1} / ${x.p.id}</span><h3>${lang==='en'?x.p.en:x.p.zh}</h3><p>${t('Compare the shape and read its interpretation','比较形状，查看纹样解读')} ↗</p></div></button>`).join('');status(t('Three visual matches are ready. Select one to compare.','已找到三个形态候选，点击即可比较。'));$('#matchResults').scrollIntoView({behavior:'smooth',block:'nearest'})}catch{status(t('Could not analyse this photo. Try a smaller selection or another image.','无法分析这张照片，请缩小框选区域或换一张图片。'))}finally{if(b.isConnected){b.disabled=false;b.removeAttribute('aria-busy');b.textContent=t('Find similar motifs →','寻找相似纹样 →')}}}
